package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.time.*;
import java.util.*;
import java.io.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real operator CLI through bootstrap -> first delegate -> approved transfer. User private keys stay in fixture RAM. */
class OwnerAdministrationCliTest {
 @TempDir Path temp;Path home;IdentityStore store;KeyPair service;byte[] audit;
 record Person(KeyPair root,KeyPair device,KeyPair recovery,KeyPair app,IdentityStore.Session session){}
 static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
 static byte[] key(KeyPair pair){return pair.getPublic().getEncoded();}
 @BeforeEach void setup()throws Exception{home=temp.resolve("operator");IdentityMain.main(new String[]{"init","--home",home.toString()});byte[] encoded=Files.readAllBytes(home.resolve("service.key"));try(var in=new DataInputStream(new ByteArrayInputStream(encoded))){assertEquals("AEGIS-IDENTITY-SERVICE/v1",in.readUTF());byte[] pub=in.readNBytes(in.readInt()),priv=in.readNBytes(in.readInt());try{service=new KeyPair(IdentityProtocol.publicKey(pub),KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(priv)));}finally{Arrays.fill(priv,(byte)0);}}finally{Arrays.fill(encoded,(byte)0);}audit=Files.readAllBytes(home.resolve("audit.key"));store=new IdentityStore(home.resolve("identity.db"),service,audit,Clock.systemUTC());}
 @AfterEach void close()throws Exception{store.close();Arrays.fill(audit,(byte)0);}
 Person register()throws Exception{KeyPair r=pair(),d=pair(),recovery=pair(),app=pair();long now=System.currentTimeMillis();String n=IdentityProtocol.nonce();byte[] body=IdentityProtocol.registration(store.audience(),key(r),key(d),key(recovery),"Участник",now,n);return new Person(r,d,recovery,app,store.register(key(r),key(d),key(recovery),"Участник",now,n,IdentityProtocol.sign(r.getPrivate(),body),IdentityProtocol.sign(d.getPrivate(),body)));}
 void step(Person p){var s=p.session();var challenge=store.stepUpChallenge(s.accountId(),s.deviceId(),s.generation());byte[] bytes=IdentityProtocol.stepUp(store.audience(),s.accountId(),s.deviceId(),challenge.challenge(),challenge.expiresAt());store.stepUp(s.accountId(),s.deviceId(),s.generation(),challenge.challenge(),IdentityProtocol.sign(p.root().getPrivate(),bytes),IdentityProtocol.sign(p.device().getPrivate(),bytes));}
 Capability cap(Person p,Scope scope){long now=System.currentTimeMillis();String n=IdentityProtocol.nonce();var s=p.session();byte[] b=IdentityProtocol.capabilityRequest(store.audience(),s.accountId(),s.deviceId(),s.generation(),App.AEGIS,key(p.app()),Set.of(scope),600000,now,n);return store.issueCapability(s.accountId(),s.deviceId(),s.generation(),App.AEGIS,key(p.app()),Set.of(scope),600000,now,n,IdentityProtocol.sign(p.device().getPrivate(),b),IdentityProtocol.sign(p.app().getPrivate(),b));}
 void json(Path file,Map<String,Object> data)throws Exception{Files.write(file,IdentityJson.bytes(data),StandardOpenOption.CREATE_NEW);}
 byte[] pop(Person p,Capability cap,byte[] body,long now,String n){return IdentityProtocol.sign(p.app().getPrivate(),IdentityProtocol.requestDigest(cap,"admin.execute",IdentityProtocol.digest(body),now,n));}
 @Test void actualCliNeedsOnlyBoundedPublicProofImportsAndPreservesRootKeys()throws Exception{
  Person owner=register(),admin=register(),target=register();String oid=owner.session().accountId(),tid=target.session().accountId();Path bootstrap=temp.resolve("bootstrap.json");IdentityMain.main(new String[]{"owner","bootstrap","--home",home.toString(),"--account-id",oid,"--challenge",bootstrap.toString()});Map<String,Object> b=IdentityJson.parse(Files.readAllBytes(bootstrap));OwnerBootstrap boot=IdentityProtocol.decodeOwnerBootstrap(IdentityProtocol.unb64((String)b.get("bootstrap"),1024));Path rootProof=temp.resolve("bootstrap-proof.json");json(rootProof,Map.of("audience",boot.audience,"accountId",boot.accountId,"challenge",boot.challenge,"signature",IdentityProtocol.b64(IdentityProtocol.sign(owner.root().getPrivate(),IdentityProtocol.ownerBootstrapBytes(boot)))));IdentityMain.main(new String[]{"owner","bootstrap","--home",home.toString(),"--account-id",oid,"--proof",rootProof.toString()});
  step(owner);Capability first=cap(owner,Scope.ADMIN);long now=System.currentTimeMillis();String n=IdentityProtocol.nonce();byte[] proposal=IdentityProtocol.firstDelegateProposal(store.audience(),oid,admin.session().accountId(),"Хранитель",now,n);Path request=temp.resolve("delegate-request.json"),challenge=temp.resolve("delegate-challenge.json");json(request,Map.of("capability",IdentityProtocol.encodeCapability(first),"targetAccountId",admin.session().accountId(),"roleName","Хранитель","time",now,"nonce",n,"proof",IdentityProtocol.b64(pop(owner,first,proposal,now,n))));IdentityMain.main(new String[]{"owner","first-delegate","--home",home.toString(),"--request",request.toString(),"--challenge",challenge.toString()});Map<String,Object> c=IdentityJson.parse(Files.readAllBytes(challenge));byte[] consent=IdentityProtocol.unb64((String)c.get("proofBytes"),2048);Path delegateProof=temp.resolve("delegate-proof.json");json(delegateProof,Map.of("challenge",c.get("challenge"),"ownerRootProof",IdentityProtocol.b64(IdentityProtocol.sign(owner.root().getPrivate(),consent)),"ownerDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(owner.device().getPrivate(),consent)),"targetRootProof",IdentityProtocol.b64(IdentityProtocol.sign(admin.root().getPrivate(),consent)),"targetDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(admin.device().getPrivate(),consent))));IdentityMain.main(new String[]{"owner","first-delegate","--home",home.toString(),"--proof",delegateProof.toString()});
  step(admin);step(target);Capability other=cap(admin,Scope.ADMIN),targetCap=cap(target,Scope.ACCOUNT_READ);now=System.currentTimeMillis();n=IdentityProtocol.nonce();proposal=IdentityProtocol.ownerTransferProposal(store.audience(),oid,tid,now,n);Path transferRequest=temp.resolve("transfer-request.json"),transferChallenge=temp.resolve("transfer-challenge.json");json(transferRequest,Map.of("capability",IdentityProtocol.encodeCapability(first),"targetAccountId",tid,"time",now,"nonce",n,"proof",IdentityProtocol.b64(pop(owner,first,proposal,now,n))));IdentityMain.main(new String[]{"owner","transfer","--home",home.toString(),"--request",transferRequest.toString(),"--challenge",transferChallenge.toString()});OwnerTransfer t=IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.unb64((String)IdentityJson.parse(Files.readAllBytes(transferChallenge)).get("transfer"),2048));byte[] payload=IdentityProtocol.ownerTransferBytes(t);now=System.currentTimeMillis();n=IdentityProtocol.nonce();byte[] exact=IdentityProtocol.criticalApproval(store.audience(),oid,"owner.transfer",n,payload,now+300000);Map<String,Object> permit=store.requestCritical(first,"owner.transfer",payload,now,n,pop(owner,first,exact,now,n));now=System.currentTimeMillis();n=IdentityProtocol.nonce();exact=IdentityProtocol.criticalApproval(store.audience(),admin.session().accountId(),"owner.transfer",(String)permit.get("requestId"),payload,(Long)permit.get("expiresAt"));store.approveCritical(other,(String)permit.get("requestId"),now,n,pop(admin,other,exact,now,n));
  byte[] ownerConsent=IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.OWNER_APPROVE),targetConsent=IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.SUCCESSOR_ACCEPT);now=System.currentTimeMillis();n=IdentityProtocol.nonce();exact=IdentityProtocol.criticalApproval(store.audience(),oid,"owner.transfer",(String)permit.get("requestId"),payload,(Long)permit.get("expiresAt"));Map<String,Object> finish=new LinkedHashMap<>();finish.put("capability",IdentityProtocol.encodeCapability(first));finish.put("challenge",t.challenge);finish.put("requestId",permit.get("requestId"));finish.put("ownerRootProof",IdentityProtocol.b64(IdentityProtocol.sign(owner.root().getPrivate(),ownerConsent)));finish.put("ownerDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(owner.device().getPrivate(),ownerConsent)));finish.put("targetRootProof",IdentityProtocol.b64(IdentityProtocol.sign(target.root().getPrivate(),targetConsent)));finish.put("targetDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(target.device().getPrivate(),targetConsent)));finish.put("time",now);finish.put("nonce",n);finish.put("proof",IdentityProtocol.b64(pop(owner,first,exact,now,n)));Path transferProof=temp.resolve("transfer-proof.json");json(transferProof,finish);IdentityMain.main(new String[]{"owner","transfer","--home",home.toString(),"--proof",transferProof.toString()});assertThrows(IdentityException.class,()->IdentityMain.main(new String[]{"owner","transfer","--home",home.toString(),"--proof",transferProof.toString()}));assertEquals(true,store.profile(tid).get("ownerBadge"));assertEquals(false,store.currentAuthority(oid).get("authorityAdministrator"));assertFalse(store.isActive(first));assertFalse(store.isActive(targetCap));assertEquals(IdentityProtocol.b64(key(owner.root())),store.publicProfile(oid).get("accountPublicKey"));assertEquals(IdentityProtocol.b64(key(target.root())),store.publicProfile(tid).get("accountPublicKey"));assertTrue(store.verifyAudit());
 }
}
